    } else {
        1.0
    };

    // Introduce imbalance penalties
    let imbalance_penalty = if imbalance > 0.5 {
        imbalance * 2.0
    } else {
        imbalance * 1.0
    };

    // Fine-grained residual fitting bonus
    let residual_fit_bonus = (node_residual_cpu as f64 / node_capacity_cpu as f64).powi(2) + (node_residual_ram as f64 / node_capacity_ram as f64).powi(2);

